1	// Event signup form — validation 純関数群
2	//
3	// 各 validator は (value) => string | null の signature。
4	// null = OK、 string = error message (日本語、 UI にそのまま表示)。
5	// validation.js は副作用なし。 DOM/Storage には触れない。
6	
7	const PLAN_VALUES = ['standard', 'premium', 'student'];
8	
9	export function validateName(value) {
10	  const trimmed = (value ?? '').trim();
11	  if (trimmed.length === 0) return '氏名は必須です';
12	  if (trimmed.length > 50) return '氏名は50文字以内で入力してください';
13	  return null;
14	}
15	
16	export function validateEmail(value) {
17	  const trimmed = (value ?? '').trim();
18	  if (trimmed.length === 0) return 'メールアドレスは必須です';
19	  const pattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
20	  if (!pattern.test(trimmed)) return 'メールアドレスの形式が正しくありません';
21	  return null;
22	}
23	
24	// 任意項目。 入力があればフォーマット検証する。
25	// 日本の電話番号: ハイフンあり/なし両対応、 数字のみ 10 or 11 桁。
26	export function validatePhone(value) {
27	  const trimmed = (value ?? '').trim();
28	  if (trimmed.length === 0) return null;
29	  const digits = trimmed.replace(/-/g, '');
30	  if (!/^\d{10,11}$/.test(digits)) return '電話番号は10桁または11桁の数字で入力してください';
31	  return null;
32	}
33	
34	export function validatePlan(value) {
35	  if (!PLAN_VALUES.includes(value)) return 'プランを選択してください';
36	  return null;
37	}
38	
39	export function validateAgreement(checked) {
40	  if (!checked) return '利用規約への同意が必要です';
41	  return null;
42	}
43	
44	export function validateForm(data) {
45	  return {
46	    name: validateName(data.name),
47	    email: validateEmail(data.email),
48	    phone: validatePhone(data.phone),
49	    plan: validatePlan(data.plan),
50	    agreement: validateAgreement(data.agreement),
51	  };
52	}
53	
54	export function hasErrors(errors) {
55	  return Object.values(errors).some((e) => e !== null);
56	}
57	
58	export const PLANS = PLAN_VALUES;
