1	import { describe, it, expect, vi, beforeEach } from 'vitest';
2	import {
3	  STORAGE_KEY,
4	  loadSubmissions,
5	  saveSubmission,
6	  submitWithDelay,
7	  buildSubmitHandler,
8	} from '../src/form.js';
9	
10	function createMockStorage() {
11	  const map = new Map();
12	  return {
13	    getItem: (k) => (map.has(k) ? map.get(k) : null),
14	    setItem: (k, v) => map.set(k, v),
15	    removeItem: (k) => map.delete(k),
16	    clear: () => map.clear(),
17	    _map: map,
18	  };
19	}
20	
21	describe('loadSubmissions', () => {
22	  it('未保存 state は [] を返す', () => {
23	    const storage = createMockStorage();
24	    expect(loadSubmissions(storage)).toEqual([]);
25	  });
26	
27	  it('JSON parse 失敗時は [] を返す (例: 不正な文字列が紛れ込んでも crash しない)', () => {
28	    const storage = createMockStorage();
29	    storage.setItem(STORAGE_KEY, 'not json');
30	    expect(loadSubmissions(storage)).toEqual([]);
31	  });
32	
33	  it('object (array でない) が入っていても [] にフォールバック', () => {
34	    const storage = createMockStorage();
35	    storage.setItem(STORAGE_KEY, JSON.stringify({ unexpected: true }));
36	    expect(loadSubmissions(storage)).toEqual([]);
37	  });
38	});
39	
40	describe('saveSubmission', () => {
41	  it('submittedAt を付与して append 保存される', () => {
42	    const storage = createMockStorage();
43	    const before = Date.now();
44	    const entry = saveSubmission(storage, { name: 'A', email: 'a@b.c' });
45	    expect(entry.name).toBe('A');
46	    expect(entry.submittedAt).toBeDefined();
47	    expect(new Date(entry.submittedAt).getTime()).toBeGreaterThanOrEqual(before);
48	
49	    const all = loadSubmissions(storage);
50	    expect(all).toHaveLength(1);
51	    expect(all[0].email).toBe('a@b.c');
52	  });
53	
54	  it('複数 submission は順序を保って append される', () => {
55	    const storage = createMockStorage();
56	    saveSubmission(storage, { name: 'A' });
57	    saveSubmission(storage, { name: 'B' });
58	    saveSubmission(storage, { name: 'C' });
59	    expect(loadSubmissions(storage).map((s) => s.name)).toEqual(['A', 'B', 'C']);
60	  });
61	});
62	
63	describe('submitWithDelay', () => {
64	  it('delayMs 後に save される', async () => {
65	    vi.useFakeTimers();
66	    const storage = createMockStorage();
67	    const promise = submitWithDelay(storage, { name: 'A' }, 100);
68	    expect(loadSubmissions(storage)).toEqual([]);
69	    await vi.advanceTimersByTimeAsync(100);
70	    await promise;
71	    expect(loadSubmissions(storage)).toHaveLength(1);
72	    vi.useRealTimers();
73	  });
74	});
75	
76	describe('buildSubmitHandler', () => {
77	  const valid = {
78	    name: '山田',
79	    email: 'y@example.com',
80	    phone: '',
81	    plan: 'standard',
82	    agreement: true,
83	  };
84	
85	  function makeContext(overrides = {}) {
86	    const setErrors = vi.fn();
87	    const setSubmitting = vi.fn();
88	    const onSuccess = vi.fn();
89	    const storage = createMockStorage();
90	    const getFormData = vi.fn(() => valid);
91	    const handler = buildSubmitHandler({
92	      getFormData,
93	      setErrors,
94	      setSubmitting,
95	      onSuccess,
96	      storage,
97	      delayMs: 0,
98	      ...overrides,
99	    });
100	    return { handler, setErrors, setSubmitting, onSuccess, storage, getFormData };
101	  }
102	
103	  it('正常 submit: validation pass → saveSubmission → onSuccess', async () => {
104	    const ctx = makeContext();
105	    const ev = { preventDefault: vi.fn() };
106	    await ctx.handler(ev);
107	    expect(ev.preventDefault).toHaveBeenCalled();
108	    expect(ctx.setErrors).toHaveBeenCalledWith(expect.objectContaining({ name: null, email: null }));
109	    expect(ctx.setSubmitting).toHaveBeenNthCalledWith(1, true);
110	    expect(ctx.setSubmitting).toHaveBeenNthCalledWith(2, false);
111	    expect(ctx.onSuccess).toHaveBeenCalledOnce();
112	    expect(loadSubmissions(ctx.storage)).toHaveLength(1);
113	  });
114	
115	  it('validation 失敗時は save も onSuccess も呼ばれない', async () => {
116	    const ctx = makeContext({ getFormData: () => ({ ...valid, email: 'bad' }) });
117	    await ctx.handler({ preventDefault: () => {} });
118	    expect(ctx.onSuccess).not.toHaveBeenCalled();
119	    expect(ctx.setSubmitting).not.toHaveBeenCalled();
120	    expect(loadSubmissions(ctx.storage)).toHaveLength(0);
121	  });
122	
123	  it('二重送信防止: submit 中の再 invoke は無視', async () => {
124	    const ctx = makeContext({ delayMs: 50 });
125	    vi.useFakeTimers();
126	    const ev1 = { preventDefault: vi.fn() };
127	    const ev2 = { preventDefault: vi.fn() };
128	    const p1 = ctx.handler(ev1);
129	    const p2 = ctx.handler(ev2); // 即座に再 click
130	    await vi.advanceTimersByTimeAsync(50);
131	    await Promise.all([p1, p2]);
132	    expect(ctx.onSuccess).toHaveBeenCalledOnce();
133	    expect(loadSubmissions(ctx.storage)).toHaveLength(1);
134	    vi.useRealTimers();
135	  });
136	});
